commentCheck(str_contains($formatted,'<pre><code>')&&str_contains($formatted,'&lt;script&gt;private()&lt;/script&gt;'),'code blocks preserve escaped original source without execution');
commentCheck(!str_contains($formatted,'<script')&&!str_contains($formatted,'<img')&&!str_contains($formatted,'href="javascript:'),'generated Markdown is sanitized again and loads no remote media or executable markup');
