$client=bin2hex(random_bytes(32));$request=bin2hex(random_bytes(32));$input=['name'=>'Own human name ä🙂','email'=>'own-comment@example.invalid','body'=>'Own exact human comment <script>alert(1)</script>','format'=>'plain'];
