commentCheck(!str_contains($publicJson,'cipher')&&!str_contains($publicJson,'author_key')&&!str_contains($publicJson,'payload_hash')&&!str_contains($publicJson,$input['email']),'public projection has no email, private cipher or identity hashes');
commentReject(fn()=>$service->moderate($pending['id'],1,'spam'),'stale moderation cannot overwrite a newer decision');
$reply=$service->submit($id,'comments',['name'=>'Own reply author','body'=>'Actual independent reply','parent'=>$pending['id']],bin2hex(random_bytes(32)),$client,'own-loopback-2',$reader);$service->moderate($reply['id'],1,'approved');
commentCheck($service->publicList($id)['total']===2,'a real separately submitted reply belongs to its exact approved parent');
