commentCheck((int)$edited['version']===3&&$edited['body']==='A deliberate human correction','a deliberate correction creates one newer human revision');
commentCheck($service->version($reply['id'],2)['body']===$originalReply['body']&&$service->version($reply['id'],1)['state']==='pending','actual original text and previous moderation decision remain independently readable');
